package system

import (
	"encoding/json"
	"errors"
	"os"
	"regexp"
	"strings"
	"testing"
	"time"

	"github.com/kyeotapp/kyeot/internal/sensor/disk"
	"github.com/kyeotapp/kyeot/internal/sensor/netwatch"
	"github.com/kyeotapp/kyeot/internal/uicatalog"
)

// testdata/computer.json is the blueprint of the app template COMPUTER (generated by scripts/gen-template-docs.mjs).
func computer(t *testing.T) []byte {
	raw, err := os.ReadFile("testdata/computer.json")
	if err != nil {
		t.Fatal(err)
	}
	return raw
}

func TestComputerTemplateFitsBundles(t *testing.T) {
	spec := computer(t)
	if _, err := uicatalog.Validate(spec); err != nil {
		t.Fatalf("template rejected: %v", err)
	}
	if w := uicatalog.Warnings(spec); len(w) != 0 {
		t.Fatalf("template warnings: %v", w)
	}
	now := time.Now()
	bundles := map[string][]any{
		netwatch.BundleName: {netwatch.New(t.TempDir(), nil).Build()},
		disk.BundleName:     {disk.Build(disk.Usage{Used: 1e9, Avail: 3e9}, nil, now), disk.Build(disk.Usage{}, errors.New("x"), now)},
		BundleName:          {Build(full(), now), Build(Sample{CPUErr: ErrUnsupported, MemErr: ErrUnsupported}, now)},
	}
	seen := map[string]int{}
	for _, m := range regexp.MustCompile(`"\$data": "([a-z]+)\.([a-z_.0-9]+)"`).FindAllStringSubmatch(string(spec), -1) {
		name, path := m[1], m[2]
		seen[name]++
		list, ok := bundles[name]
		if !ok {
			t.Errorf("bundle %s that the server doesn't measure", name)
			continue
		}
		for _, b := range list {
			raw, _ := json.Marshal(b)
			var v any
			json.Unmarshal(raw, &v)
			for _, k := range strings.Split(path, ".") {
				obj, _ := v.(map[string]any)
				var has bool
				if v, has = obj[k]; !has {
					t.Errorf("bundle %s has no %s", name, path)
					break
				}
			}
		}
	}
	for name := range bundles {
		if seen[name] == 0 {
			t.Errorf("blueprint does not read bundle %s", name)
		}
	}
	raw, _ := json.Marshal(Build(full(), now))
	if w := uicatalog.DataWarnings([]json.RawMessage{spec}, BundleName, raw); len(w) != 0 {
		t.Errorf("system bundle warnings: %v", w)
	}
}
